#!/usr/bin/env python3
import argparse,json,subprocess,sys
p=argparse.ArgumentParser();p.add_argument('--manifest',required=True);p.add_argument('--source-sha',required=True);p.add_argument('--config-sha',required=True);p.add_argument('--deployed-sha',required=True);p.add_argument('--brain-sha',required=True);p.add_argument('--health-json',required=True);a=p.parse_args();m=json.load(open(a.manifest));h=json.loads(a.health_json);vals=[m.get('candidate_sha'),a.source_sha,a.config_sha,a.deployed_sha,a.brain_sha];checks={'shaAgreement':len(set(vals))==1,'servicesHealthy':bool(h.get('servicesHealthy')),'leasesSane':bool(h.get('leasesSane')),'claimsSane':bool(h.get('claimsSane')),'schedulerHealthy':bool(h.get('schedulerHealthy')),'workerRegistryCompatible':bool(h.get('workerRegistryCompatible')),'schemasCurrent':bool(h.get('schemasCurrent')),'verificationAuthorityHealthy':bool(h.get('verificationAuthorityHealthy')),'integrationAuthorityHealthy':bool(h.get('integrationAuthorityHealthy'))};print(json.dumps({'ok':all(checks.values()),'checks':checks},sort_keys=True));sys.exit(0 if all(checks.values()) else 1)
